import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ToastRequest{Title: "Achievement", Message: "You earned Taking Inventory!"}
TOAST = bytes.fromhex("0b416368696576656d656e741c596f75206561726e65642054616b696e6720496e76656e746f727921")

# generated by gophertunnel b8bd735:
# &packet.ToastRequest{}
EMPTY = bytes.fromhex("0000")

# generated by gophertunnel b8bd735:
# &packet.ToastRequest{Message: strings.Repeat("x", 200)}
LONG_CONTENT = bytes.fromhex(
    "00c801"
    "78787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "78787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "78787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "78787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "78787878787878787878787878787878787878787878787878787878787878787878787878787878"
)

GOLDENS = [
    pytest.param(
        v2225.ToastRequestPacket(title="Achievement", content="You earned Taking Inventory!"), TOAST, id="toast"
    ),
    pytest.param(v2225.ToastRequestPacket(), EMPTY, id="empty"),
    pytest.param(v2225.ToastRequestPacket(content="x" * 200), LONG_CONTENT, id="two-byte-varint-length"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_toast_request_is_packet_186(version):
    assert version.packets[186] is version.ToastRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_toast_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_toast_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
